INSERT INTO `notifications` VALUES
('core','core_bindaddress_changed',500,'Updated Asterisk Mini HTTP Server Bind Address to Localhost','Asterisk Mini HTTP Server bind address updated from \"::\" to \"127.0.0.1\" to restrict access to localhost and improve security.','?display=advancedsettings&view=category&category_id=Asterisk%20Builtin%20mini-HTTP%20server',0,1,1793330132),
('core','EXTENSIONS_MOVE',600,'Extensions now located within \'Connectivity\' category','The \'Extensions\' menu item previously listed under \'Applications\' has been relocated to the \'Connectivity\' menu.','',0,1,1793330132),
('framework','BROWSER_STATS',600,'Collecting Anonymous Browser Stats','The FreePBX project is collecting anonymous browser statistics using google analytics. These are used to focus development efforts based on real user input. All information is anonymous. You can disable this in Advanced Settings with the Browser Stats setting.','',0,1,1793330150),
('framework','missing_html5',600,'Missing HTML5 format converters','You are missing support for the following HTML5 codecs: m4a. To fully support HTML5 browser playback you will need to install programs that can not be distributed with FreePBX. If you\'d like to install the binaries needed for these conversions click \'Resolve\' in the lower left corner of this message. You can also safely ignore this message but browser playback might not work in your browser.','https://sangomakb.atlassian.net/wiki/spaces/FP/pages/10682566/Installing+Media+Conversion+Libraries',0,1,1793330150),
('freepbx','UPDATEEMAIL',400,'Failed to send update notification email','An attempt to send an email to \"\" with update notifications failed','',0,0,1793331056),
